window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[296]={"id":"296","numero":296,"titre":"Agranulocytose médicamenteuse","objectifs":[{"id":"296-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’agranulocytose","contenu":"<p>L'<span class=\"kw-def\">agranulocytose médicamenteuse</span> est un <span class=\"kw-alerte\">accident hématologique iatrogène</span> fréquent — elle représente <span class=\"kw-chiffre\">2,4 %</span> de l'ensemble des accidents iatrogéniques.</p>\n    <p>Deux définitions coexistent :</p>\n    <ul>\n      <li><strong>Définition théorique :</strong> <span class=\"kw-def\">absence totale de polynucléaires neutrophiles</span> (PNN) circulants.</li>\n      <li><strong>Définition pratique :</strong> <span class=\"kw-bio\">neutropénie profonde de grade IV</span>, retenue dès que <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">PNN sont <span class=\"kw-chiffre\">&lt; 0,5 G/L</span></span>.</li>\n    </ul>\n    <p>Le <span class=\"kw-alerte\">pronostic reste mauvais</span> : on observe encore <span class=\"kw-alerte\">~5 % de décès</span>, et ce <span class=\"kw-chiffre\">même lorsque la prise en charge est précoce</span> et adaptée — ce qui justifie de considérer toute agranulocytose comme une <span class=\"kw-alerte\">urgence</span>.</p>\n    <div class=\"callout callout-info\"><strong>À distinguer.</strong> L'<span class=\"kw-def\">aplasie médullaire</span> se définit sur l'étude de la <span class=\"kw-clinique\">moelle osseuse</span>, et non sur la <span class=\"kw-bio\">NFS</span> : <span class=\"kw-def\">agranulocytose</span> (anomalie du sang) et <span class=\"kw-def\">aplasie</span> (anomalie de la moelle) ne sont pas synonymes.</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 212 — <span class=\"kw-bio\">Hémogramme</span> · 191 — <span class=\"kw-clinique\">Fièvre</span> chez l'immunodéprimé</em></p>","frequence":1},{"id":"296-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes d'une agranulocytose médicamenteuse","contenu":"<p>L'agranulocytose médicamenteuse relève de <span class=\"kw-def\">deux mécanismes</span> distincts, dont la distinction conditionne l'atteinte des autres lignées et le <span class=\"kw-def\">pronostic</span>.</p>\n    <table >\n      <thead><tr><th>Critère</th><th><span class=\"kw-etio\">Toxique</span> <span class=\"kw-chiffre\">(plus fréquent)</span></th><th>Immuno-<span class=\"kw-etio\">allergique</span> <span class=\"kw-chiffre\">(plus rare)</span></th></tr></thead>\n      <tbody>\n        <tr>\n          <td>Cible</td>\n          <td><strong>Atteinte centrale :</strong> <span class=\"kw-def\">aplasie médullaire</span> ; <br>hypoplasie puis aplasie de <span class=\"kw-clinique\">toutes les lignées myéloïdes</span> (arrêt de croissance des progéniteurs) aboutissant à une <span class=\"kw-alerte\">pancytopénie</span></td>\n          <td><strong>Atteinte périphérique :</strong> destruction immuno-<span class=\"kw-etio\">allergique</span> de <span class=\"kw-clinique\">la seule lignée granulocytaire</span> ; <span class=\"kw-clinique\">les</span> autres lignées sont <span class=\"kw-bio\">épargnées</span></td>\n        </tr>\n        <tr>\n          <td>Lien à la dose</td>\n          <td><span class=\"kw-chiffre\">Dose-dépendante</span> possible</td>\n          <td><span class=\"kw-chiffre\">Indépendante de la dose</span></td>\n        </tr>\n        <tr>\n          <td>Sensibilisation</td>\n          <td>Pas de sensibilisation préalable nécessaire</td>\n          <td><span class=\"kw-alerte\">Sensibilisation préalable indispensable :</span> traitement de <span class=\"kw-chiffre\">~11 jours</span>, ou <span class=\"kw-def\">contact</span> ancien <span class=\"kw-def\">suivi</span> d'une <span class=\"kw-clinique\">réintroduction</span></td>\n        </tr>\n        <tr>\n          <td>Installation</td>\n          <td><span class=\"kw-clinique\">Progressive</span>, <span class=\"kw-chiffre\">2 à 10 jours</span> après la <span class=\"kw-ttt\">chimiothérapie</span></td>\n          <td><span class=\"kw-alerte\">Aiguë, brutale</span></td>\n        </tr>\n        <tr>\n          <td>Médicaments</td>\n          <td><strong><span class=\"kw-ttt\">Chimiothérapie</span> :</strong> prévisible, majorité des cas ; <br><strong><span class=\"kw-ttt\">Psychotropes</span> :</strong> rare, non prévisible</td>\n          <td><span class=\"kw-ttt\">Clozapine</span> ; <span class=\"kw-ttt\">antithyroïdiens</span> (carbimazole) ; <span class=\"kw-ttt\">dapsone</span> ; <span class=\"kw-ttt\">pénicilline G</span> ; <span class=\"kw-ttt\">défériprone</span> ; <span class=\"kw-ttt\">ticlopidine</span> ; <span class=\"kw-ttt\">procaïnamide</span> ; <span class=\"kw-ttt\">rituximab</span> ; <span class=\"kw-ttt\">sulfasalazine</span></td>\n        </tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-info\"><strong>Conséquence pratique.</strong> Le mécanisme <span class=\"kw-def\">toxique</span> retentit sur <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">3 lignées</span> (anémie et thrombopénie associées) ; le mécanisme <span class=\"kw-def\">immuno-allergique</span> donne une <span class=\"kw-bio\">agranulocytose isolée</span> (PNN seuls effondrés).</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 74 — Psychotropes · 242 — <span class=\"kw-def\">Hyperthyroïdie</span> · 315 — Leucémie aiguë</em></p>","frequence":1},{"id":"296-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les circonstances de découverte d'une agranulocytose médicamenteuse","contenu":"<p>Une <span class=\"kw-def\">agranulocytose médicamenteuse</span> peut être révélée selon <span class=\"kw-chiffre\">trois circonstances</span> :</p>\n    <ul>\n      <li><strong><span class=\"kw-bio\">NFS</span> systématique :</strong> <span class=\"kw-def\">dépistage</span> lors de la <span class=\"kw-bio\">surveillance hématologique programmée</span> d'un médicament à risque (<span class=\"kw-ttt\">chimiothérapie</span>, <span class=\"kw-ttt\">clozapine</span>, antithyroïdiens).</li>\n      <li><strong>Tableau <span class=\"kw-etio\">infectieux</span> :</strong> découverte sur une <span class=\"kw-alerte\">fièvre brutale</span>, une <span class=\"kw-clinique\">angine</span> ou des <span class=\"kw-clinique\">lésions muqueuses</span> inexpliquées.</li>\n      <li><strong>Découverte fortuite :</strong> <span class=\"kw-bio\">NFS</span> demandée pour un tout autre motif.</li>\n    </ul>\n    <p>Le <span class=\"kw-clinique\">mode d'installation</span> oriente d'emblée vers le mécanisme :</p>\n    <table >\n      <thead><tr><th>Mécanisme</th><th>Installation</th><th><span class=\"kw-def\">Terrain</span></th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">Toxique</span></td><td><span class=\"kw-clinique\">Progressive</span>, <span class=\"kw-chiffre\">2 à 10 jours</span> après la cure de <span class=\"kw-ttt\">chimiothérapie</span></td><td>Patient traité pour cancer ou hémopathie</td></tr>\n        <tr><td><span class=\"kw-def\">Immuno-allergique</span></td><td><span class=\"kw-alerte\">Brutale</span>, aiguë</td><td><span class=\"kw-clinique\">Adulte</span>, avec <span class=\"kw-clinique\">prédominance féminine</span></td></tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-info\"><strong>Réflexe.</strong> Devant toute <span class=\"kw-alerte\">fièvre ou angine</span> chez un patient sous médicament à risque, demander une <span class=\"kw-bio\">NFS en urgence</span> : c'est elle qui affirme l'agranulocytose.</div>","frequence":1},{"id":"296-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes du tableau infectieux","contenu":"<p>Le déficit profond en <span class=\"kw-bio\">polynucléaires neutrophiles</span> expose à un <span class=\"kw-alerte\">tableau infectieux</span> qui peut s'installer et s'aggraver très vite.</p>\n    <ul>\n      <li><strong><span class=\"kw-clinique\">Fièvre</span> :</strong> souvent <span class=\"kw-clinique\">isolée</span>, et parfois seule manifestation de l'infection.</li>\n      <li><strong><span class=\"kw-alerte\">Angine ulcéro-nécrotique</span> :</strong> tableau <span class=\"kw-clinique\">extrêmement évocateur</span> d'agranulocytose.</li>\n      <li><strong>Lésions ulcéro-nécrotiques muqueuses :</strong> <span class=\"kw-clinique\">hyperalgiques</span> et <span class=\"kw-clinique\">creusantes</span>, de topographie surtout <span class=\"kw-clinique\">buccale</span>, exposant à la <span class=\"kw-alerte\">surinfection</span>.</li>\n      <li><strong>Absence de pus :</strong> le <span class=\"kw-clinique\">déficit en PNN empêche la formation de pus</span> — l'infection peut être sévère malgré des signes locaux pauvres.</li>\n    </ul>\n    <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Toute infection peut évoluer en quelques heures vers un <span class=\"kw-alerte\">sepsis</span> puis un <span class=\"kw-alerte\">choc septique</span> : la <span class=\"kw-clinique\">fièvre</span> du patient agranulocytaire est une urgence d'évaluation et de traitement.</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 191 — <span class=\"kw-clinique\">Fièvre</span> chez l'immunodéprimé</em></p>","frequence":1},{"id":"296-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes sur l’Hémogramme","contenu":"<p>La <span class=\"kw-bio\">NFS</span> est l'examen qui affirme le diagnostic : elle montre des <span class=\"kw-bio\">PNN effondrés</span> (<span class=\"kw-chiffre\">&lt; 0,5 G/L</span>). L'atteinte des <span class=\"kw-clinique\">autres lignées</span> dépend du mécanisme.</p>\n    <table >\n      <thead><tr><th>Lignée</th><th>Mécanisme <span class=\"kw-etio\">toxique</span> (<span class=\"kw-ttt\">chimiothérapie</span>)</th><th>Mécanisme immuno-<span class=\"kw-etio\">allergique</span></th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-bio\">PNN</span></td><td><span class=\"kw-alerte\">Agranulocytose ± totale</span></td><td><span class=\"kw-alerte\">Agranulocytose souvent complète</span> (<span class=\"kw-chiffre\">PNN à 0 G/L</span>)</td></tr>\n        <tr><td><span class=\"kw-bio\">Hémoglobine</span></td><td><span class=\"kw-bio\">Anémie</span> quasi-constante</td><td>Habituellement <span class=\"kw-clinique\">pas d'anémie</span></td></tr>\n        <tr><td><span class=\"kw-bio\">Plaquettes</span></td><td><span class=\"kw-bio\">Thrombopénie</span> quasi-constante</td><td>Habituellement <span class=\"kw-clinique\">pas de thrombopénie</span></td></tr>\n        <tr><td>Synthèse</td><td><span class=\"kw-alerte\">Pancytopénie</span> — <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> l</span>ignées sont atteintes</td><td><span class=\"kw-bio\">Agranulocytose isolée</span> — <span class=\"kw-clinique\">les</span> PNN seuls</td></tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-info\"><strong>Lecture rapide.</strong> Une <span class=\"kw-bio\">agranulocytose isolée</span>, sans anémie ni thrombopénie, oriente vers le mécanisme <span class=\"kw-def\">immuno-allergique</span> ; une <span class=\"kw-alerte\">pancytopénie</span> oriente vers une atteinte centrale <span class=\"kw-def\">toxique</span> (aplasie médullaire).</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 212 — <span class=\"kw-bio\">Hémogramme</span> · 213 — Anémie · 214 — Thrombopénie</em></p>","frequence":2},{"id":"296-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître l’indication du myélogramme","contenu":"<p>Le <span class=\"kw-bio\">myélogramme</span> est <span class=\"kw-alerte\">indispensable devant toute agranulocytose</span>, <span class=\"kw-ci\">sauf si elle est secondaire à une chimiothérapie anticancéreuse</span> (le mécanisme est alors déjà connu).</p>\n    <table >\n      <thead><tr><th>Rôle</th><th>Données du myélogramme</th></tr></thead>\n      <tbody>\n        <tr><td><strong>Diagnostic</strong></td><td>Moelle de <span class=\"kw-bio\">richesse diminuée</span>, avec <span class=\"kw-clinique\">disparition totale ou partielle de la lignée granuleuse</span> ; <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">autres lignées sont respectées</span> (mégacaryocytes, érythroblastes, <span class=\"kw-bio\">lymphocytes</span>, plasmocytes)</td></tr>\n        <tr><td><strong><span class=\"kw-def\">Pronostic</span></strong></td><td><strong>Soit absence totale</strong> de la lignée granuleuse ; <br><strong>soit <span class=\"kw-clinique\">blocage de maturation au stade promyélocyte</span> :</strong> myéloblastes et promyélocytes présents, <span class=\"kw-alerte\">sans corps ni fagots d'Auer</span> (ce qui <span class=\"kw-ci\">écarte une leucémie aiguë promyélocytaire / LAM3</span>), avec <span class=\"kw-bio\">absence d'éléments plus matures</span> — témoin d'un <span class=\"kw-clinique\">début de reprise de la granulopoïèse</span></td></tr>\n        <tr><td><strong>Étiologique</strong></td><td>Élimine <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">diagnostics différentiels</span> (<span class=\"kw-bio\">envahissement</span> médullaire, syndrome myélodysplasique)</td></tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-info\"><strong>Piège.</strong> La présence de <span class=\"kw-alerte\">corps ou de fagots d'Auer</span> n'appartient PAS à l'agranulocytose médicamenteuse : elle doit faire évoquer une <span class=\"kw-def\">leucémie aiguë</span>.</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 315 — Leucémie aiguë · 316 — Syndrome myélodysplasique</em></p>","frequence":1},{"id":"296-7","rang":"A","rubrique":"Etiologie","titre":"Savoir conduire l’enquête étiologique","contenu":"<p>L'enquête étiologique repose avant tout sur l'<span class=\"kw-clinique\">interrogatoire</span> : <span class=\"kw-alerte\">tout médicament nouvellement introduit est potentiellement responsable</span>. De très nombreuses classes thérapeutiques peuvent être en cause :</p>\n    <ul>\n      <li><span class=\"kw-ttt\">Antithyroïdiens de synthèse</span></li>\n      <li><span class=\"kw-ttt\">Psychotropes</span></li>\n      <li><span class=\"kw-ttt\">Anticonvulsivants</span></li>\n      <li><span class=\"kw-ttt\">Anti-inflammatoires</span></li>\n      <li><span class=\"kw-ttt\">Antibiotiques</span></li>\n      <li><span class=\"kw-ttt\">Antidiabétiques</span></li>\n      <li><span class=\"kw-ttt\">Médicaments à tropisme cardiovasculaire</span></li>\n    </ul>\n    <table >\n      <thead><tr><th>Catégorie</th><th>Principaux médicaments à connaître</th></tr></thead>\n      <tbody>\n        <tr><td>Psychotrope</td><td><span class=\"kw-ttt\">Clozapine</span></td></tr>\n        <tr><td>Antithyroïdien</td><td><span class=\"kw-ttt\">Carbimazole</span></td></tr>\n        <tr><td>Antibiotiques</td><td><span class=\"kw-ttt\">Dapsone</span> ; <span class=\"kw-ttt\">pénicilline G</span> à forte dose</td></tr>\n        <tr><td>Chélateur du fer</td><td><span class=\"kw-ttt\">Défériprone</span></td></tr>\n        <tr><td>Autres</td><td><span class=\"kw-ttt\">Ticlopidine</span> ; <span class=\"kw-ttt\">procaïnamide</span> ; <span class=\"kw-ttt\">rituximab</span> ; <span class=\"kw-ttt\">sulfasalazine</span></td></tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-danger\"><strong>Pharmacovigilance.</strong> Tout accident d'agranulocytose médicamenteuse doit être <span class=\"kw-alerte\">déclaré au Centre Régional de Pharmacovigilance (CRPV)</span>. <span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">critères d'imputabilité</span> sont établis par ces centres.</div>\n    <p>Plusieurs <span class=\"kw-bio\">tests biologiques</span> ont été proposés — <span class=\"kw-bio\">culture des progéniteurs médullaires</span> en présence et en l'absence du sérum du patient et du médicament en cause, <span class=\"kw-bio\">immunofluorescence</span> recherchant des <span class=\"kw-bio\">anticorps anti-granulocytes</span> — mais <span class=\"kw-ci\">aucun n'est parfait, simple à réaliser, ni utilisé en pratique courante</span>.</p>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 325 — Risque <span class=\"kw-etio\">médicamenteux</span>, <span class=\"kw-etio\">iatrogène</span> · 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":1},{"id":"296-8","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les éléments clés de la prise en charge","contenu":"<p>L'<span class=\"kw-def\">agranulocytose médicamenteuse</span> est une <span class=\"kw-alerte\">urgence</span> : sa reconnaissance impose des gestes immédiats, indépendamment de la présence d'une <span class=\"kw-clinique\">fièvre</span>.</p>\n    <ul>\n      <li><strong><span class=\"kw-alerte\">Arrêt immédiat et définitif</span> du <span class=\"kw-ttt\">médicament suspect</span></strong> — un <span class=\"kw-clinique\">certificat est remis au patient</span> (<span class=\"kw-ci\">contre-indication à vie</span>).</li>\n      <li><strong><span class=\"kw-clinique\">Hospitalisation</span></strong> avec <span class=\"kw-clinique\">isolement protecteur</span>.</li>\n      <li><strong>Si le patient est <span class=\"kw-clinique\">fébrile</span> :</strong> <span class=\"kw-ttt\">antibiothérapie IV à large spectre en urgence</span>, après <span class=\"kw-bio\">prélèvements</span>, sans attendre la <span class=\"kw-bio\">documentation microbiologique</span> (modalités de la <span class=\"kw-alerte\">neutropénie fébrile</span>).</li>\n      <li><strong>Déclaration au <span class=\"kw-alerte\">CRPV</span></strong> (<span class=\"kw-etio\">pharmacovigilance</span>).</li>\n    </ul>\n    <div class=\"callout callout-danger\"><strong>À ne pas manquer.</strong> Une <span class=\"kw-alerte\">fièvre</span> chez un <span class=\"kw-clinique\">patient agranulocytaire</span> peut évoluer en quelques heures vers un <span class=\"kw-alerte\">choc septique</span> : l'<span class=\"kw-ttt\">antibiothérapie probabiliste</span> ne se discute pas, elle s'administre sans délai.</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 191 — <span class=\"kw-clinique\">Fièvre</span> chez l'immunodéprimé · 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span></em></p>","frequence":2},{"id":"296-9","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître le pronostic de l’agranulocytose dans le cadre d’une aplasie médullaire post-chimiothérapique","contenu":"<p>Dans le cadre d'une <span class=\"kw-def\">aplasie médullaire post-chimiothérapique</span>, la <span class=\"kw-clinique\">durée de la neutropénie</span> — et donc le <span class=\"kw-def\">pronostic</span> — dépend directement de l'<span class=\"kw-clinique\">intensité de la chimiothérapie</span> et de la <span class=\"kw-clinique\">maladie traitée</span>.</p>\n    <table >\n      <thead><tr><th>Contexte</th><th>Durée de la neutropénie</th><th>Conséquence</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-ttt\">Chimiothérapie</span> pour <span class=\"kw-clinique\">cancer solide</span></td><td><span class=\"kw-bio\">Neutropénie</span> <span class=\"kw-chiffre\">&lt; 7 jours</span></td><td><span class=\"kw-clinique\">Récupération généralement rapide</span></td></tr>\n        <tr><td><span class=\"kw-ttt\">Chimiothérapie</span> pour <span class=\"kw-clinique\">hémopathie</span></td><td><span class=\"kw-bio\">Neutropénie</span> <span class=\"kw-chiffre\">&gt; 7 jours</span></td><td><span class=\"kw-alerte\">Majorité des admissions en soins intensifs / réanimation</span></td></tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-info\"><strong>Repère.</strong> Le seuil de <span class=\"kw-chiffre\">7 jours</span> de <span class=\"kw-bio\">neutropénie</span> sépare <span class=\"kw-clinique\">les</span> situations de <span class=\"kw-clinique\">faible risque</span> (<span class=\"kw-clinique\">cancers solides</span>) des situations <span class=\"kw-alerte\">prolongées à haut risque</span> (<span class=\"kw-clinique\">hémopathies</span>), où s'ajoute le risque d'<span class=\"kw-alerte\">infection fongique invasive</span>.</div>","frequence":1},{"id":"296-10","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître le pronostic de l’agranulocytose dans le cadre d’une aplasie médullaire médicamenteuse accidentelle","contenu":"<p>Dans le cadre d'une <span class=\"kw-def\">aplasie médullaire médicamenteuse accidentelle</span> (mécanisme <span class=\"kw-def\">immuno-allergique</span>), la récupération suit une <span class=\"kw-clinique\">séquence caractéristique</span> après l'<span class=\"kw-ttt\">arrêt du médicament</span> :</p>\n    <ul>\n      <li><span class=\"kw-bio\">Monocytose</span> annonçant la <span class=\"kw-clinique\">reprise</span>, <span class=\"kw-chiffre\">~48 h avant</span> la <span class=\"kw-bio\">réascension des PNN</span> ;</li>\n      <li>puis <span class=\"kw-bio\">myélémie</span> ;</li>\n      <li>puis <span class=\"kw-bio\">polynucléose de rebond</span>.</li>\n    </ul>\n    <p>La <span class=\"kw-bio\">réascension des PNN au-dessus de <span class=\"kw-chiffre\">0,5 G/L</span></span> survient habituellement <span class=\"kw-chiffre\">vers 8 à 10 jours</span> ; la <span class=\"kw-clinique\">durée totale de l'agranulocytose</span> varie de <span class=\"kw-chiffre\">quelques jours à 3 semaines</span>.</p>\n    <div class=\"callout callout-danger\"><strong><span class=\"kw-def\">Pronostic</span>.</strong> Malgré une <span class=\"kw-clinique\">évolution souvent favorable</span>, la <span class=\"kw-clinique\">mortalité persiste</span> à <span class=\"kw-alerte\">~5 % des cas</span>. L'<span class=\"kw-alerte\">arrêt du médicament est définitif</span>, avec remise d'un <span class=\"kw-clinique\">certificat au patient</span>.</div>","frequence":0},{"id":"296-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge de l’agranulocytose aiguë médicamenteuse","contenu":"<p>La prise en charge de l'<span class=\"kw-def\">agranulocytose aiguë médicamenteuse</span> est une <span class=\"kw-alerte\">urgence</span> qui combine l'arrêt de la cause, la prévention et le traitement des infections, et la <span class=\"kw-def\">surveillance</span> jusqu'à récupération.</p>\n    <table >\n      <thead><tr><th>Volet</th><th>Mesures</th></tr></thead>\n      <tbody>\n        <tr><td><strong>Médicament en cause</strong></td><td><span class=\"kw-alerte\">Arrêt immédiat et définitif</span> du médicament suspect ; <span class=\"kw-clinique\">certificat remis au patient</span> ; <span class=\"kw-alerte\">déclaration au CRPV</span></td></tr>\n        <tr><td><strong>Mesures anti-infectieuses</strong></td><td><span class=\"kw-clinique\">Hospitalisation</span> ; <span class=\"kw-clinique\">isolement protecteur</span> ; recherche et traitement de tout <span class=\"kw-clinique\">foyer infectieux</span></td></tr>\n        <tr><td><strong>Si <span class=\"kw-clinique\">fièvre</span></strong></td><td><span class=\"kw-ttt\">Antibiothérapie probabiliste à large spectre, IV, en urgence</span>, après prélèvements (modalités de la neutropénie fébrile)</td></tr>\n        <tr><td><strong>Facteur de croissance</strong></td><td><span class=\"kw-ttt\">G-CSF</span> dans certaines situations : <span class=\"kw-clinique\">raccourcit la durée de la neutropénie</span> (d'environ <span class=\"kw-chiffre\">48 h</span>)</td></tr>\n        <tr><td><strong>Mesures locales</strong></td><td><span class=\"kw-ttt\">Bains de bouche</span> pour limiter le risque de mucite et de surinfection</td></tr>\n        <tr><td><strong><span class=\"kw-def\">Surveillance</span></strong></td><td><span class=\"kw-bio\">NFS répétée</span> jusqu'à la <span class=\"kw-bio\">récupération des PNN <span class=\"kw-chiffre\">&gt; 0,5 G/L</span></span></td></tr>\n      </tbody>\n    </table>\n    <div class=\"callout callout-danger\"><strong>Objectif central de l'item.</strong> Deux réflexes indissociables : <span class=\"kw-alerte\">arrêter le médicament</span> et, devant toute <span class=\"kw-alerte\">fièvre</span>, débuter sans délai une <span class=\"kw-ttt\">antibiothérapie probabiliste</span> — le <span class=\"kw-alerte\">pronostic vital</span> se joue dans <span class=\"kw-clinique\">les</span> premières heures.</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 191 — <span class=\"kw-clinique\">Fièvre</span> chez l'immunodéprimé · 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":5}],"astuces":[],"strategie":{"urgence":"<p><strong>Arrêt du médicament en cause</strong></p><p>Déclaration au <span class=\"kw-alerte\">CRPV</span> (<span class=\"kw-etio\">pharmacovigilance</span>) — accident à signaler impérativement</p><ul><li><span class=\"kw-alerte\">Arrêt immédiat et définitif</span> du <span class=\"kw-ttt\">médicament suspect</span> dès la reconnaissance de l'agranulocytose</li><li><span class=\"kw-clinique\">Certificat remis au patient</span> mentionnant la <span class=\"kw-ci\">contre-indication à vie</span></li></ul><p><strong>Si <span class=\"kw-clinique\">fièvre</span> <span class=\"q\">— neutropénie fébrile</span></strong></p><p>Le <span class=\"kw-alerte\">pronostic vital</span> se joue dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">premières heures</span> : l'<span class=\"kw-ttt\">antibiothérapie</span> ne se discute pas, elle s'administre sans délai</p><ul><li><span class=\"kw-ttt\">Antibiothérapie probabiliste à large spectre, IV, en urgence</span></li><li>Débutée <span class=\"kw-chiffre\">après prélèvements</span> (<span class=\"kw-bio\">hémocultures</span>), <span class=\"kw-alerte\">sans attendre la documentation microbiologique</span></li></ul>","hospit":"<p><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> systématique, avec <span class=\"kw-clinique\">isolement protecteur</span> (milieu protégé).<br><strong>Chambre stérile :</strong> <span class=\"kw-def\">air</span> filtré à <span class=\"kw-chiffre\">pression positive</span> / flux laminaire si <span class=\"kw-chiffre\">neutropénie &gt; 7 jours</span> (risque <span class=\"kw-alerte\">fongique invasif</span> surajouté).<br><strong><span class=\"kw-alerte\">Soins intensifs</span> / réanimation :</strong> majorité des admissions en cas de <span class=\"kw-clinique\">neutropénie prolongée</span> (hémopathie).</p>","redflags":"<ul><li><span class=\"kw-alerte\">Fièvre</span> chez un patient <span class=\"kw-clinique\">agranulocytaire</span> → <span class=\"kw-clinique\">évolution</span> possible en quelques heures vers un <span class=\"kw-alerte\">sepsis</span> puis un <span class=\"kw-alerte\">choc septique</span></li><li><span class=\"kw-alerte\">Angine ulcéro-nécrotique</span> — tableau extrêmement évocateur d'agranulocytose</li><li><span class=\"kw-clinique\">Lésions ulcéro-nécrotiques muqueuses</span> hyperalgiques et creusantes (buccales ++) exposant à la <span class=\"kw-alerte\">surinfection</span></li><li><span class=\"kw-alerte\">Absence de pus</span> : le déficit en <span class=\"kw-bio\">PNN</span> empêche sa formation — signes locaux pauvres alors que l'infection est sévère</li><li><span class=\"kw-alerte\">Pancytopénie</span> (<span class=\"kw-bio\">anémie</span> + <span class=\"kw-bio\">thrombopénie</span> associées) → atteinte centrale <span class=\"kw-etio\">toxique</span> / <span class=\"kw-def\">aplasie médullaire</span></li></ul>","principes":"<p>Deux réflexes indissociables : <span class=\"kw-alerte\">arrêter le médicament</span> en cause et, devant toute <span class=\"kw-alerte\">fièvre</span>, débuter sans délai une <span class=\"kw-ttt\">antibiothérapie probabiliste</span> — le <span class=\"kw-alerte\">pronostic vital</span> se joue dans <span class=\"kw-clinique\">les</span> premières heures.</p><p><strong>Médicament en cause</strong></p><p>Déclaration au <span class=\"kw-alerte\">CRPV</span> (<span class=\"kw-etio\">pharmacovigilance</span>)</p><ul><li><span class=\"kw-alerte\">Arrêt immédiat et définitif</span> du <span class=\"kw-ttt\">médicament suspect</span></li><li><span class=\"kw-clinique\">Certificat remis au patient</span> (<span class=\"kw-ci\">contre-indication à vie</span>)</li></ul><p><strong>Mesures anti-infectieuses</strong></p><ul><li><span class=\"kw-clinique\">Hospitalisation</span> avec <span class=\"kw-clinique\">isolement protecteur</span></li><li>Recherche et traitement de tout <span class=\"kw-clinique\">foyer infectieux</span></li><li><span class=\"kw-ttt\">Bains de bouche</span> pour limiter le risque de mucite et de surinfection</li></ul><p><strong>Si <span class=\"kw-clinique\">fièvre</span></strong></p><p>Modalités de la <span class=\"kw-alerte\">neutropénie fébrile</span> (cf. item 191 — <span class=\"kw-clinique\">fièvre chez l'immunodéprimé</span>)</p><ul><li><span class=\"kw-ttt\">Antibiothérapie probabiliste à large spectre, IV, en urgence</span>, après <span class=\"kw-bio\">prélèvements</span></li></ul><p><strong>Facteur de croissance</strong></p><ul><li><span class=\"kw-ttt\">G-CSF</span> dans certaines situations (neutropénie prolongée, infection des parties molles)</li><li>Raccourcit la durée de la <span class=\"kw-bio\">neutropénie</span> d'environ <span class=\"kw-chiffre\">48 h</span></li></ul>","suivi":"<p><strong><span class=\"kw-def\">Surveillance</span> clé :</strong> <span class=\"kw-bio\">NFS répétée</span> jusqu'à la <span class=\"kw-bio\">récupération des PNN &gt; 0,5 G/L</span>.</p><p><strong>Récupération <span class=\"q\">— aplasie médicamenteuse accidentelle</span></strong></p><ul><li><span class=\"kw-bio\">Monocytose</span> annonçant la reprise (<span class=\"kw-chiffre\">~48 h avant</span> la réascension des PNN), puis <span class=\"kw-bio\">myélémie</span>, puis <span class=\"kw-bio\">polynucléose de rebond</span></li><li>Réascension des <span class=\"kw-bio\">PNN &gt; 0,5 G/L</span> vers <span class=\"kw-chiffre\">8 à 10 jours</span></li><li>Durée totale de l'agranulocytose : <span class=\"kw-chiffre\">quelques jours à 3 semaines</span></li></ul><p><strong><span class=\"kw-def\">Pronostic</span> <span class=\"q\">— aplasie post-chimiothérapique</span></strong></p><ul><li><span class=\"kw-clinique\">Cancers solides</span> : <span class=\"kw-bio\">neutropénie</span> <span class=\"kw-chiffre\">&lt; 7 jours</span>, récupération généralement rapide</li><li><span class=\"kw-clinique\">Hémopathies</span> : <span class=\"kw-bio\">neutropénie</span> <span class=\"kw-chiffre\">&gt; 7 jours</span>, <span class=\"kw-alerte\">infection fongique invasive</span> surajoutée, majorité des admissions en <span class=\"kw-alerte\">soins intensifs</span></li></ul><p><strong><span class=\"kw-def\">Pronostic</span> global</strong></p><ul><li><span class=\"kw-alerte\">Mortalité ~5 %</span> qui persiste malgré une prise en charge précoce et adaptée</li><li><span class=\"kw-alerte\">Arrêt définitif</span> du médicament, avec <span class=\"kw-clinique\">certificat remis au patient</span></li></ul>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-191.pdf","label":"Pilly étudiant — Pilly 2023 item 191"}],"cards":[{"i":"23bfb6e6f7a7","n":296,"o":"296-1","u":"Définition","t":"Connaître la définition de l’agranulocytose","q":"Quelle est la définition théorique de l'agranulocytose médicamenteuse ?","a":"<p>L'agranulocytose médicamenteuse est définie théoriquement par l'<strong>absence totale</strong> de polynucléaires neutrophiles (PNN) circulants.</p>"},{"i":"516b251e380b","n":296,"o":"296-1","u":"Définition","t":"Connaître la définition de l’agranulocytose","q":"Quelle est la définition pratique de l'agranulocytose médicamenteuse, et quel est le seuil retenu ?","a":"<p>La définition pratique de l'agranulocytose médicamenteuse correspond à une <strong>neutropénie profonde de grade IV</strong>, retenue dès lors que les PNN sont <strong>&lt; 0,5 G/L</strong>.</p>"},{"i":"5285fc62cfee","n":296,"o":"296-1","u":"Définition","t":"Connaître la définition de l’agranulocytose","q":"Quel est le pronostic de l'agranulocytose médicamenteuse et pourquoi est-elle considérée comme une urgence ?","a":"<p>Le pronostic de l'agranulocytose médicamenteuse reste <strong>mauvais</strong>, avec environ <strong>5% de décès</strong> même en cas de prise en charge précoce et adaptée. Elle est considérée comme une <strong>urgence vitale</strong>.</p>"},{"i":"fce8966f099d","n":296,"o":"296-1","u":"Définition","t":"Connaître la définition de l’agranulocytose","q":"Comment différencier une agranulocytose d'une aplasie médullaire ?","a":"<p>L'<strong>agranulocytose</strong> est une anomalie portant sur le <strong>sang circulant</strong> (neutropénie sur la NFS), tandis que l'<strong>aplasie médullaire</strong> est définie par une anomalie de la <strong>moelle osseuse</strong>.</p>"},{"i":"100722388dd7","n":296,"o":"296-11","u":"Prise en charge","t":"Connaître les principes de prise en charge de l’agranulocytose aiguë médicamenteuse","q":"Comment doit être surveillée l'évolution d'une agranulocytose aiguë médicamenteuse et jusqu'à quand ?","a":"<p>L'évolution doit être surveillée par des <strong>numérations formules sanguines (NFS) répétées</strong> et ce, jusqu'à la <strong>récupération des polynucléaires neutrophiles (PNN) à un seuil supérieur à 0,5 G/L</strong>.</p>"},{"i":"46b06b6a9d3d","n":296,"o":"296-11","u":"Prise en charge","t":"Connaître les principes de prise en charge de l’agranulocytose aiguë médicamenteuse","q":"Quel est le rôle du G-CSF (Facteur de Croissance Granulocytaire) dans la prise en charge de l'agranulocytose aiguë médicamenteuse ?","a":"<p>Le G-CSF peut être utilisé dans certaines situations. Son rôle est de <strong>raccourcir la durée de la neutropénie</strong>, généralement d'environ <strong>48 heures</strong>, favorisant ainsi la récupération des neutrophiles.</p>"},{"i":"b2215a9db21d","n":296,"o":"296-11","u":"Prise en charge","t":"Connaître les principes de prise en charge de l’agranulocytose aiguë médicamenteuse","q":"Quelles sont les mesures anti-infectieuses à mettre en place face à une agranulocytose aiguë médicamenteuse ?","a":"<p>Les mesures anti-infectieuses incluent :</p><ul><li>Une <strong>hospitalisation</strong> en urgence.</li><li>Un <strong>isolement protecteur</strong> du patient.</li><li>La recherche et le traitement de tout foyer infectieux.</li><li>En cas de fièvre, l'instauration immédiate d'une <strong>antibiothérapie probabiliste à large spectre par voie IV</strong>, après prélèvements, selon les modalités de la neutropénie fébrile.</li></ul>"},{"i":"c1949c1f7f51","n":296,"o":"296-11","u":"Prise en charge","t":"Connaître les principes de prise en charge de l’agranulocytose aiguë médicamenteuse","q":"Quelle est la première mesure à prendre en charge une agranulocytose aiguë médicamenteuse ?","a":"<p>La première mesure est l'<strong>arrêt immédiat et définitif du médicament suspect</strong> à l'origine de l'agranulocytose. Il faut également fournir un certificat au patient et effectuer une <strong>déclaration au CRPV</strong> (Centre Régional de Pharmacovigilance).</p>"},{"i":"59997e0b0233","n":296,"o":"296-3","u":"Diagnostic positif","t":"Connaître les circonstances de découverte d'une agranulocytose médicamenteuse","q":"Comment un tableau infectieux peut-il révéler une agranulocytose médicamenteuse ?","a":"<p>Un tableau infectieux peut révéler une agranulocytose médicamenteuse par l'apparition d'une <strong>fièvre brutale</strong>, d'une <strong>angine</strong> ou de <strong>lésions muqueuses inexpliquées</strong>.</p>"},{"i":"a754611d7314","n":296,"o":"296-3","u":"Diagnostic positif","t":"Connaître les circonstances de découverte d'une agranulocytose médicamenteuse","q":"En présence de quel type de symptômes un patient sous médicament à risque doit-il bénéficier d'une NFS en urgence pour affirmer une agranulocytose ?","a":"<p>Devant toute <strong>fièvre</strong> ou <strong>angine</strong> chez un patient sous médicament à risque, une NFS doit être demandée en urgence pour affirmer l'agranulocytose.</p>"},{"i":"cf30f7871f5f","n":296,"o":"296-3","u":"Diagnostic positif","t":"Connaître les circonstances de découverte d'une agranulocytose médicamenteuse","q":"Quelle est la première circonstance de découverte d'une agranulocytose médicamenteuse, comme spécifié dans le contenu source ?","a":"<p>La première circonstance est une <strong>NFS systématique</strong>, réalisée dans le cadre d'un dépistage lors de la surveillance hématologique programmée d'un médicament à risque. Cela concerne notamment la <strong>chimiothérapie</strong>, la <strong>clozapine</strong> et les <strong>antithyroïdiens</strong>.</p>"},{"i":"eaa946ec54f6","n":296,"o":"296-3","u":"Diagnostic positif","t":"Connaître les circonstances de découverte d'une agranulocytose médicamenteuse","q":"Au-delà des NFS systématiques et d'un tableau infectieux, quel autre mode de découverte de l'agranulocytose médicamenteuse est mentionné ?","a":"<p>Il est également mentionné une <strong>découverte fortuite</strong> lors d'une NFS demandée pour un tout autre motif.</p>"},{"i":"3d458b46f355","n":296,"o":"296-4","u":"Diagnostic positif","t":"Connaître les signes du tableau infectieux","q":"Quelle est la lésion buccale la plus évocatrice d'une agranulocytose ?","a":"<p>La lésion la plus évocatrice est l'<strong>angine ulcéro-nécrotique</strong>, qui constitue un tableau clinique fortement suggestif d'agranulocytose. D'une manière générale, des <strong>lésions ulcéro-nécrotiques muqueuses</strong>, particulièrement buccales, hyperalgiques et creusantes, sont très évocatrices.</p>"},{"i":"727b7c3d11f3","n":296,"o":"296-4","u":"Diagnostic positif","t":"Connaître les signes du tableau infectieux","q":"Quelle est l'évolution potentielle et la gravité de toute infection chez un patient agranulocytaire ?","a":"<p>Toute infection chez un patient agranulocytaire est une véritable <strong>urgence</strong>. Elle peut évoluer <strong>très rapidement</strong>, en quelques heures, vers un <strong>sepsis</strong>, puis un <strong>choc septique</strong>. La fièvre chez ce type de patient nécessite une évaluation et un traitement immédiats.</p>"},{"i":"8bdbd16e6be3","n":296,"o":"296-4","u":"Diagnostic positif","t":"Connaître les signes du tableau infectieux","q":"Pourquoi l'absence de pus est-elle une caractéristique importante des infections chez un patient présentant une agranulocytose ?","a":"<p>L'absence de pus est due au <strong>déficit profond en polynucléaires neutrophiles</strong> (PNN), qui sont les cellules essentielles à la formation du pus. Cette particularité fait que l'infection peut être <strong>sévère</strong> malgré des <strong>signes locaux pauvres</strong> et peu flamboyants.</p>"},{"i":"ec09dd8c0d9e","n":296,"o":"296-4","u":"Diagnostic positif","t":"Connaître les signes du tableau infectieux","q":"Quel est le signe clinique inaugural le plus fréquent du tableau infectieux en cas d'agranulocytose et quelles sont ses caractéristiques ?","a":"<p>Le signe clinique le plus fréquent est la <strong>fièvre</strong>. Elle est souvent <strong>isolée</strong> et peut être la <strong>seule manifestation</strong> de l'infection. Elle doit être considérée comme une urgence chez le patient agranulocytaire.</p>"},{"i":"10bfc4703b7b","n":296,"o":"296-5","u":"Diagnostic positif","t":"Connaître les signes sur l’Hémogramme","q":"Dans le diagnostic d'une agranulocytose médicamenteuse, quelles sont les atteintes des autres lignées (hémoglobine et plaquettes) qui orientent vers un mécanisme immuno-allergique ?","a":"<p>Un mécanisme immuno-allergique est suggéré par :</p><ul><li>Généralement <strong>pas d'anémie</strong>.</li><li>Généralement <strong>pas de thrombopénie</strong>.</li><li>L'atteinte est alors une <strong>agranulocytose isolée</strong>, les PNN étant souvent à 0 G/L.</li></ul>"},{"i":"3dc738a1fcdb","n":296,"o":"296-5","u":"Diagnostic positif","t":"Connaître les signes sur l’Hémogramme","q":"Dans le diagnostic d'une agranulocytose médicamenteuse, quelles sont les atteintes des autres lignées (hémoglobine et plaquettes) qui orientent vers un mécanisme toxique (type chimiothérapie) ?","a":"<p>Un mécanisme toxique est suggéré par :</p><ul><li>Une <strong>anémie quasi-constante</strong> (atteinte de l'hémoglobine).</li><li>Une <strong>thrombopénie quasi-constante</strong> (atteinte des plaquettes).</li><li>La coexistence de ces atteintes avec l'agranulocytose aboutissant à une <strong>pancytopénie</strong>.</li></ul>"},{"i":"e3036dbdb39c","n":296,"o":"296-5","u":"Diagnostic positif","t":"Connaître les signes sur l’Hémogramme","q":"Comment l'hémogramme définit-il l'agranulocytose, notamment dans le contexte d'une agranulocytose médicamenteuse ?","a":"<p>L'hémogramme affirme le diagnostic d'agranulocytose médicamenteuse par un effondrement des polynucléaires neutrophiles (PNN) à une concentration <strong>inférieure à 0,5 G/L</strong>.</p>"},{"i":"3febb1db5f97","n":296,"o":"296-6","u":"Diagnostic positif","t":"Connaître l’indication du myélogramme","q":"Dans quel contexte clinique réalise-t-on un myélogramme pour une agranulocytose ?","a":"<p>Un myélogramme est indispensable devant toute <strong>agranulocytose</strong>, sauf si celle-ci est secondaire à une <strong>chimiothérapie anticancéreuse</strong>, où le mécanisme est déjà connu.</p>"},{"i":"6364a1aa2f4b","n":296,"o":"296-6","u":"Diagnostic positif","t":"Connaître l’indication du myélogramme","q":"Que peut montrer le myélogramme pour évaluer le pronostic d'une agranulocytose et quels pièges éviter ?","a":"<p>Pour le pronostic d'une agranulocytose, le myélogramme peut montrer :</p><ul><li>Une absence totale de la lignée granuleuse, ou un <strong>blocage de maturation au stade promyélocyte</strong>.</li><li>La présence de <strong>myéloblastes et promyélocytes</strong> est observée, mais sans corps ni fagots d'Auer, ce qui écarte une leucémie aiguë. L'absence d'éléments plus matures témoigne d'un début de reprise de la granulopoïèse.</li></ul><p><strong>Piège :</strong> La présence de <strong>corps ou de fagots d'Auer n'appartient PAS à l'agranulocytose médicamenteuse</strong> et doit faire évoquer une leucémie aiguë.</p>"},{"i":"a1d408a30e81","n":296,"o":"296-6","u":"Diagnostic positif","t":"Connaître l’indication du myélogramme","q":"Comment le myélogramme aide-t-il au diagnostic différentiel d'une agranulocytose ?","a":"<p>Le myélogramme permet d'éliminer les diagnostics différentiels d'une agranulocytose tels qu'un <strong>envahissement médullaire</strong> ou un <strong>syndrome myélodysplasique</strong>.</p>"},{"i":"d844fb634586","n":296,"o":"296-6","u":"Diagnostic positif","t":"Connaître l’indication du myélogramme","q":"Quelles sont les données attendues d'un myélogramme dans le diagnostic positif d'une agranulocytose ?","a":"<p>Dans une agranulocytose, le myélogramme montre :</p><ul><li>Une <strong>diminution de la richesse médullaire</strong>, avec disparition totale ou partielle de la lignée granuleuse.</li><li>Les autres lignées (mégacaryocytes, érythroblastes, lymphocytes, plasmocytes) sont <strong>respectées</strong>.</li></ul>"},{"i":"60b70503e7fb","n":296,"o":"296-7","u":"Etiologie","t":"Savoir conduire l’enquête étiologique","q":"Quelle est la conduite à tenir médico-légale en cas d'agranulocytose médicamenteuse suspectée ?","a":"<p>Tout accident d'agranulocytose médicamenteuse doit être <strong>déclaré au Centre Régional de Pharmacovigilance (CRPV)</strong>. Ce sont ces centres qui établissent les critères d'imputabilité.</p>"},{"i":"6283c82310c6","n":296,"o":"296-7","u":"Etiologie","t":"Savoir conduire l’enquête étiologique","q":"Quelle est la première étape et le pilier de l'enquête étiologique d'une agranulocytose médicamenteuse ?","a":"<p>La première étape et le pilier de l'enquête étiologique est l'<strong>interrogatoire</strong>. Il vise à identifier tout <strong>médicament nouvellement introduit</strong>.</p>"},{"i":"a4bb6e72a811","n":296,"o":"296-7","u":"Etiologie","t":"Savoir conduire l’enquête étiologique","q":"Quelles sont les principales classes thérapeutiques à suspecter en cas d'agranulocytose médicamenteuse, selon le contenu donné ?","a":"<ul><li><strong>Antithyroïdiens de synthèse</strong></li><li><strong>Psychotropes</strong></li><li><strong>Anticonvulsivants</strong></li><li><strong>Anti-inflammatoires</strong></li><li><strong>Antibiotiques</strong></li><li><strong>Antidiabétiques</strong></li><li><strong>Médicaments à tropisme cardiovasculaire</strong></li></ul>"},{"i":"e0e167f66d9b","n":296,"o":"296-7","u":"Etiologie","t":"Savoir conduire l’enquête étiologique","q":"Quels sont les exemples de médicaments spécifiques à connaître pouvant induire une agranulocytose ?","a":"<ul><li>Psychotrope : <strong>Clozapine</strong></li><li>Antithyroïdien : <strong>Carbimazole</strong></li><li>Antibiotiques : <strong>Dapsone</strong>, <strong>pénicilline G à forte dose</strong></li><li>Chélateur du fer : <strong>Défériprone</strong></li><li>Autres : <strong>Ticlopidine</strong>, <strong>procaïnamide</strong>, <strong>rituximab</strong>, <strong>sulfasalazine</strong></li></ul>"},{"i":"fa8fca9b9e92","n":296,"o":"296-7","u":"Etiologie","t":"Savoir conduire l’enquête étiologique","q":"Existe-t-il des tests biologiques fiables et couramment utilisés pour confirmer l'imputabilité médicamenteuse dans l'agranulocytose ?","a":"<p>Non. Bien que plusieurs tests biologiques aient été proposés (culture des progéniteurs médullaires, recherche d'anticorps anti-granulocytes), <strong>aucun n'est parfait, simple à réaliser, ni utilisé en pratique courante</strong>.</p>"},{"i":"2c114fc38002","n":296,"o":"296-8","u":"Identifier une urgence","t":"Connaître les éléments clés de la prise en charge","q":"Quelle est la conduite à tenir en cas de fièvre chez un patient agranulocytaire suspect d'agranulocytose médicamenteuse ?","a":"<p>En cas de fièvre, une <strong>antibiothérapie IV à large spectre en urgence</strong> doit être instaurée après la réalisation de prélèvements, sans attendre la documentation microbiologique. La fièvre chez un patient agranulocytaire peut évoluer rapidement vers un choc septique.</p>"},{"i":"91174c13e18b","n":296,"o":"296-8","u":"Identifier une urgence","t":"Connaître les éléments clés de la prise en charge","q":"Quelle est la première mesure à prendre en cas de suspicion d'agranulocytose médicamenteuse, même en l'absence de fièvre ?","a":"<p>La première mesure est l'<strong>arrêt immédiat et définitif du médicament suspect</strong>. Un certificat de contre-indication à vie doit être remis au patient.</p>"},{"i":"a5193c1ed981","n":296,"o":"296-8","u":"Identifier une urgence","t":"Connaître les éléments clés de la prise en charge","q":"Quelle est l'obligation administrative en cas d'agranulocytose médicamenteuse ?","a":"<p>Une <strong>déclaration au CRPV (Centre Régional de Pharmacovigilance)</strong> est obligatoire pour signaler cet effet indésirable grave au médicament.</p>"},{"i":"f3971d0816a0","n":296,"o":"296-8","u":"Identifier une urgence","t":"Connaître les éléments clés de la prise en charge","q":"Quelles sont les mesures d'isolement et de surveillance à mettre en place pour un patient présentant une agranulocytose médicamenteuse ?","a":"<p>Une <strong>hospitalisation avec isolement protecteur</strong> est nécessaire afin de prévenir les infections, étant donné le risque élevé chez un patient agranulocytaire.</p>"}]};